      "ヴァルス": "【相性: 極めて不利】<br>射程差で無理にCSを取りに行かず、E1を温存してQポークを回避する。RやWのバーストで捕まると厳しいため、5以降はフラッシュ込みの一気の接近を狙う。",
      "ヴェイン": "【相性: 極めて不利】<br>通常のE→W→Qだけで追い切ろうとせず、Eの再使用をヴェインのE後に合わせる。序盤はCSと経験値を優先し、無理な長時間追撃をしない。",
      "ウーコン": "【相性: 有利】<br>Wの分身を追わず、本体のQ・Eの再使用タイミングに合わせて短いトレードを入れる。こちらのWは分身処理より本体への確実なスタンに使う。",
      "ウディア": "【相性: 有利】<br>接近してきたところへW→Qで短く返し、Eは追撃か離脱のために残す。覚醒スキルをまとめて受けず、最初のバーストをしのいでから反撃する。",
      "エイトロックス": "【相性: 五分】<br>E1でAatroxのWを外し、E2でQ3を避けるのが最重要。Qのスイートスポットを受けながら長く殴らず、こちらの短いバーストを先に当てる。",
      "オーロラ": "【相性: 不利】<br>遠距離ハラスを無理に追い、Wを先に使わない。オーロラの逃げスキル後にE2まで使って距離を詰め、5以降はR中の再配置を意識して捕まえる。",
      "オーン": "【相性: 有利】<br>オーンのW中に無理にスタンを合わせようとせず、W終了後を狙う。強化Wでシールドを削れる場面を作り、5以降はRでの耐久差を活かす。",
      "オラフ": "【相性: 不利】<br>オラフのR中はCCを当てに行かず、EやWを無駄にしない。Qの斧を外させてから短く削り、長いオールインは避ける。",
      "カ・サンテ": "【相性: 不利】<br>Eの壁移動とR後の追撃を警戒し、先に全ダッシュを使い切らない。序盤の短いトレードで体力差を作り、オールアウト時は一気にW→Qで削る。",
      "ガングプランク": "【相性: 有利】<br>樽の体力が1になった瞬間の先壊しを狙う。樽の連鎖を避けてからEで接近し、Wを確実に当てる。ガングプランクのWによるCC解除も意識してRのタイミングを選ぶ。",
