      "ザック": "【相性: 有利】<br>Eの着地点へW→Qを合わせ、分裂細胞を放置しない。長く追いかけるより、細胞を処理しながらウェーブを押し込む。",
      "シェン": "【相性: 有利】<br>Wの通常攻撃無効化中に無理にAAを重ねず、QとEで削る。R詠唱を見たらEの位置を意識して中断を狙う。",
      "ジェイス": "【相性: 不利】<br>遠距離Qのポークはミニオン越しに受け、無理に正面から歩かない。ハンマーEを使った後が接近チャンスなので、そこに二段Eを合わせる。",
