      "シンジド": "【相性: 有利】<br>毒の中を追い続けず、ウェーブ処理を優先する。シンジドがWを使った後は逃げ道が狭くなるので、そこにE→W→Qを合わせる。",
      "スウェイン": "【相性: 五分】<br>Eの引き寄せを横移動で避け、R中に無理に長居しない。回復が強いので短いバーストを複数回入れ、オールインは味方と合わせる。",
      "スカーナー": "【相性: 五分】<br>壁際を避け、Eでの突進とRのキャッチを警戒する。先にダッシュを切らず、スカーナーの接近後にWで反撃する。",
