    "アーゴット":"【相性: 有利寄り】Lv1〜2は射程差で小さく削り、EはアーゴットEを見てから使う。Lv3〜4はEを温存してQの当たり戻りを確保し、5以降は処刑Rを受けないHP管理を徹底。1コア以降はサイドで無理な長追いをせず、Eフラッシュには自分のE/フラッシュを合わせる。",
