    "イラオイ":"【相性: 五分】Lv1は押して先にウェーブを作り、E(触手)を最優先で避ける。Eを外させた時間だけ短く交換し、5以降は触手が少ない位置でメガを使う。1コア以降は回復阻害が有効なら早めに用意し、R中は正面で殴り続けない。",
    "イレリア":"【相性: 極めて不利】Lv1はEスタートも候補で、前衛ミニオン2体程度を取ってQ接近を誘い、Eで自陣側へ跳ねる。Lv3以降はEを常に残し、70%HPを下回る無理な前プッシュを避ける。5以降はメガ＋JGでのみ強い勝負を作る。",
    "ヴァルス":"【相性: 不利】序盤はQをファーム優先にしてポーク勝負をしない。Lv3以降はEを接近用に温存し、相手のE/RやQチャージ後に距離を詰める。5以降はメガで一度の接近機会を作るまで無理をせず、1コア後も正面から歩いて入らない。",
    "ヴェイン":"【相性: 不利】Lv1〜4はQをCSに使い、通常攻撃の射程勝負をしない。Eはコンデム後の追撃回避に残し、5以降にメガで一気に捕まえる。1コア前はCS差を許容しても死亡を避け、ゴースト採用なら追撃より離脱にも使う。",
    "ウーコン":"【相性: 不利】Lv1は押し合いより安全重視。W分身とE接近を見てからEで離脱し、短いWプロックだけ取る。5以降はメガで受けてウーコンRの最初の回転をかわし、サイドの長期戦は避ける。",
    "ウディア":"【相性: 有利寄り】序盤は射程差で小さく削り、ウディアの覚醒スキルをまとめて受けない。Lv3以降は接近の直前にEで距離を取り、Wの3回目を狙う。5以降も単純な長期戦ではなく、メガで確実にクラッシュやオールインを作る。",
    "エイトロックス":"【相性: 五分】最初の数ウェーブはCSとウェーブ優先で、Q1/Q2をEで外せる角度を作る。Lv3以降はEをQ2回避かW解除用に残し、Q3やWを外させた瞬間だけ追う。1コア後は移動速度と短い交換で外周Qを拒否する。",
    "オーロラ":"【相性: 不利】序盤は射程差を我慢し、W/Eを先に吐いて距離を詰めない。Lv3以降はオーロラの逃げ手段を見てからEを切り、5以降はメガのCCで捕まえる時だけ大きく動く。1コア前はCS・HPの両立を優先。",
    "オーン":"【相性: 有利】Lv1〜4は積極的にウェーブ主導権を取り、オーンのQ/Wを使わせてから短く交換。5以降はR付きのガンク・オールインだけ警戒し、メガでクラッシュする。1コア後は長いタンク戦よりサイド圧をかけ、HPが有利ならプレートを回収。",
    "オラフ":"【相性: 五分】Lv1〜3は斧を避けながらQでポークし、オラフが斧を外した時間だけ攻める。5以降はR中のCCを狙わず、メガの間に距離を取る。1コア以降はオラフの回復込みの長期戦を避け、ウェーブと移動速度で勝負する。",
    "カ・サンテ":"【相性: 有利寄り】Lv1は先に押して、Qスタートなら無理に殴り続けない。Lv3以降はEで距離を維持し、Eがある限り小さなポークを重ねる。5以降はR後のオールアウト追撃だけ警戒し、1コア後はブラッククリーバー系の耐久削りを活かす。",
    "ガングプランク":"【相性: 有利】Lv1〜4は樽を殴る暇を与えず、Q・AAで主導権を取る。樽2個連結を避け、GPのW解除後にメガR/Wを重ねる。5以降はグローバルRでサイド差を作られないようウェーブを先に処理し、1コア後は樽の射線を切る。",
