        timeline: "【Lv1〜2】最初のウェーブでは無理にキルを取りに行かず、Qでファームと回復を確保。<br>【Lv3〜4】E1→W→Q→E2の短い交換が本領。相手の主要CC・逃げスキルが落ちた瞬間に仕掛ける。<br>【Lv5以降】RでHP差をひっくり返しやすくなる。勝てる対面ではウェーブ主導権をそのままプレート・ローム・オブジェクトへ変換。<br>【1〜2コア】最もリードを広げやすい時間帯。終盤に備えてサイドや集団戦で早期リードを使い切る。"
