        timeline: "【Lv1〜4】Qのスタックを作ってEと通常攻撃を織り交ぜ、短い交換を重ねる。遠距離対面ではWを防御用に温存。<br>【Lv5〜1コア】R取得後はQ・E・通常攻撃の継続火力が大きく伸びる。相手の主要CCをW/Eで外してから入る。<br>【1〜3コア】黄昏と暁 / ナッシャー トゥース / リフトメーカーを対面と戦闘時間で分岐。<br>【終盤】高APによるスケールを活かし、Wで遠距離スキルを遮りながらRを複数回当てる。"
