    function getOrnnMatchupDetails(enemyName) { return ornnMatchupDetails[enemyName] || ornnMatchupDetails.default; }
    function getOrnnFirstCore(enemyName) { const d=ornnMatchupDetails[enemyName] || ornnMatchupDetails.default; return { item:d.recommended, reason:d.reason }; }

    function getGnarFirstCore(enemyName) { return gnarFirstCore[enemyName] || gnarFirstCore.default; }

    function getGwenFirstCore(enemyName) {
      return gwenFirstCore[enemyName] || gwenFirstCore.default;
    }

    function getChampionSpellTip(champName, enemyName) {
      const specific = matchupSpellTips[champName]?.[enemyName];
      if (specific) return specific;

      // モルデカイザー：MOBAFire高レートTop資料を最優先。
      // 基本はFlash + Ignite。勝てる対面ではキル確定力を優先し、
      // レンジ/ポークや明確に不利な対面だけTeleportへ寄せる。
      if (champName === 'モルデカイザー') {
        const disposition = getMatchupDisposition(champName, enemyName, false);
        if (['グウェン','ダリウス','フィオラ','トリンダメア','イラオイ'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋イグナイト。MOBAFireのMordekaiser対面資料では、回復力が高くオールイン勝負になりやすい対面でIgniteを明示的に推奨。WRでもFlash + Igniteを標準として扱う。';
        }
        if (enemyName === 'ワーウィック') {
          return '【サモナースペル】フラッシュ＋テレポート。早期ブランブル系防具が必要な対面では回復阻害がアイテム側で確保できるため、イグナイトよりレーン復帰・マクロ価値を優先。';
        }
        if (disposition === 'disadvantage' || ['ヴァルス','ヴェイン','カシオペア','クイン','ハイマーディンガー'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋テレポート。序盤のキル圧が低いレンジ/ポーク・不利対面では、レーン復帰とウェーブ維持を優先。Lv5以降はRで1vs1を作れるので、TPは立て直しとマクロのために使う。';
        }
        if (disposition === 'advantage') {
          return '【サモナースペル】フラッシュ＋イグナイト。高い1vs1性能を活かせる有利対面では、R内のオールインに追加ダメージ＋回復阻害を重ねて確実に倒し切り、序盤のリードを広げる。';
        }
        return '【サモナースペル】フラッシュ＋イグナイトを基本。五分の近接対面でも、モルデカイザーは継続戦闘とRによる1vs1強制が強いため、キル圧と回復阻害を優先する。';
      }
      if (champName === 'レネクトン' && renektonAudit[enemyName]) {
        return `【サモナースペル】${renektonAudit[enemyName].spell}。${renektonAudit[enemyName].tier === 'advantage' ? '有利対面ではIgniteでキルラインを押し上げる。' : renektonAudit[enemyName].tier === 'extreme_disadvantage' ? 'レーン維持と復帰を優先してTeleportを選ぶ。' : '対面の接近・継続戦闘条件に合わせて選択。'}`;
      }
      if (champName === 'レネクトン') {
        return '【サモナースペル】フラッシュ＋イグナイトを基本。現行PCのTop統計でもIgniteが明確な標準で、MOBAFire高レート資料でもレーン主導権とキル圧を重視する。Quinn等の明確な例外だけTeleportへ分岐する。';
      }
      if (champName === 'エイトロックス') {
        // エイトロックスは現行WRでFlash + Igniteが明確な標準。
        // PC側の高レート資料でもIgniteのレーン圧を重視する傾向が確認できるため、
        // 旧DBの「不利対面＝TP」という一括判定は廃止する。
        // TPは明確な例外理由がある対面だけに限定する。
        if (enemyName === 'フィオラ') {
          return '【サモナースペル】フラッシュ＋テレポート。TP例外として確定。MOBAFireではAatrox側の非常に難しい対面として扱われ、Q/WをRiposteで止められるため無理なオールインを避け、レーン復帰・ウェーブ維持を優先する考え方が確認できる。OnetricksでもAatrox OTP側の対面データが大きく有利とは言えず、WR側でもFioraはAatroxの主要カウンター。';
        }
        // 再監査済み：TP例外として根拠が十分なのはフィオラのみ。
        // オーン/サイオン/シェン/スカーナー/タム・ケンチ/ザーヘンは、
        // MOBAFire・Onetricks・WR資料を突き合わせた結果、Aatrox側の標準Igniteを崩すほどの
        // 対面固有TP根拠が確認できないため、Igniteへ戻す。
        return '【サモナースペル】フラッシュ＋イグナイトを基本。Qの交換からキルラインを作り、オールインの確定力と回復阻害を優先する。テレポートは明確なマクロ上の理由がある場合だけ選択。';
      }
      if (champName === 'グウェン') {
        // グウェンはWR現行Diamond+でFlash + Igniteが明確な標準。
        // PCの高レート資料はTP/Ghost/Exhaustなど選択肢が広いが、WRではFlashを固定し、
        // 対面固有の根拠がある場合だけ2枠目を変更する。
        if (enemyName === 'リヴェン') {
          return '【サモナースペル】フラッシュ＋イグゾースト。MOBAFireのChallenger Gwen資料ではRiven専用にExhaustを採用し、Rivenのコンボ/Rを軽減して長い戦闘を成立させる。WRではFlashを維持してExhaustを合わせる。';
        }
        if (['フィオラ','エイトロックス','ザック'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋イグナイト。MOBAFireのChallenger Gwen資料では回復力の高いFiora/Aatrox/ZacにIgniteを推奨し、オールインのキルラインと回復阻害を重視。WR側でもFlash + Igniteが標準。';
        }
        if (['ダリウス','イレリア'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋イグナイト。MOBAFireではDariusはIgniteが必須、Ireliaも序盤の主導権確保のためIgniteを採用する考え方が明記されている。WRの標準構成とも一致。';
        }
        if (['ナー','ケネン','ジェイス','ヴェイン','クイン','ティーモ'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋ゴーストを候補。レンジ対面ではキル確定用Igniteより、接近・追撃・離脱のための移動性能の価値が上がる。MOBAFireでもGwenのGhostはkite対策として評価されている。ただしWRの現行標準はFlash + Igniteなので、Ghostは対面適応候補。';
        }
        if (['オーン','サイオン','マルファイト','チョーガス','ドクター・ムンド'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋イグナイトを基本。タンク対面ではIgniteによる早期キル圧を優先し、TPへ変更するほどの対面固有根拠は現時点では不足。';
        }
        if (enemyName === 'アーゴット') {
          return '【サモナースペル】フラッシュ＋イグナイトを基本。MOBAFireでは序盤のEを避けて短いQ交換を行い、後半は1v1より5v5を重視するが、Ignite以外を必須とする根拠は確認できない。';
        }
        return '【サモナースペル】フラッシュ＋イグナイトを基本。現行WR Diamond+ではFlash + Igniteが70.71%で明確な標準。PC高レートではTP/Ghost等の選択肢もあるが、対面固有の強い根拠がない限りWR標準を優先する。';
      }
      if (champName === 'オーン') {
        if ([...rangedEnemies].includes(enemyName)) return '【サモナースペル】フラッシュ＋テレポートを基本。遠距離対面ではレーン復帰と集団戦合流を優先し、キル用スペルより安全性を重視する。';
        if (["ガングプランク","シンジド","ケイル","シェン"].includes(enemyName)) return '【サモナースペル】フラッシュ＋テレポートを基本。ウェーブ処理後にテレポートでマップの数的差を作る。';
        if (["グウェン","フィオラ","レネクトン","イレリア"].includes(enemyName)) return '【サモナースペル】フラッシュ＋テレポートを基本。序盤を耐えて1コア以降の集団戦へ持ち込む。';
        return '【サモナースペル】フラッシュ＋テレポートを基本。R始動・Eフラッシュ・視界確保で集団戦に先手を取る。';
      }
      if (champName === 'ナー') {
        // PC版高レートTopを第一基準。MOBAFire現行Top統計ではFlash + Teleportが68%、
        // Flash + Igniteが20%。高評価GnarガイドもTeleportを標準、Igniteを明確に雪玉化できる対面の選択肢としている。
        if (['ティーモ','ガングプランク','ドクター・ムンド'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋イグナイト。MOBAFire高評価Gnar資料では、早期にレーンを雪玉化できるTeemo/Gangplank、回復・長期戦対策が重要なDr. MundoではIgniteの価値が上がる。';
        }
        if (['ヴェイン','クイン','ケネン','ジェイス','ヴァルス','オーロラ','カシオペア','トリスターナ','ツイステッド・フェイト','ハイマーディンガー','ライズ','ブラッドミア','ケイル'].includes(enemyName)) {
          return '【サモナースペル】フラッシュ＋テレポート。レンジ対面でもまずはウェーブ・復帰・マクロを優先。Ghostを標準化する根拠は現行MOBAFire資料では不足しているため、対面例外にはしない。';
        }
        return '【サモナースペル】フラッシュ＋テレポートを基本。現行PC Top統計で明確に主流で、高評価Gnarガイドでも標準スペル。Igniteは明確にレーンを雪玉化できる対面に限定する。';
      }
      return null;
    }


    // 現行Wild Riftの対面データで明示されるカウンターは、既存Tipsより優先して判定。
    // 7.2d時点: モルデカイザーはフィオラ/イレリア/ランブル、レネクトンはナー/ティーモ/モルデカイザー、
    // グウェンはフィオラ/トリンダメア/リヴェンが対面注意。アーゴットはモルデカイザー側の有利寄りとして扱う。
    const currentWrRuneOverrides = {
      "モルデカイザー": {
        advantage: new Set(["アーゴット"]),
        disadvantage: new Set(["フィオラ", "イレリア", "ランブル"])
      },
      "レネクトン": {
        advantage: new Set([]),
        disadvantage: new Set(["ナー", "ティーモ", "モルデカイザー"])
      },
      "グウェン": {
        advantage: new Set([]),
        disadvantage: new Set(["フィオラ", "トリンダメア", "リヴェン"])
      },
      "ナー": { advantage: new Set([]), disadvantage: new Set([]) },
      "オーン": { advantage: new Set(), disadvantage: new Set() }
    };

    // 勝てる対面では攻撃寄り、不利対面では守備寄りという「対面→ルーン」判定。
    function getMatchupDisposition(champName, enemyName, fallbackUnfavorable) {
      if (champName === "レネクトン" && renektonAudit[enemyName]) return renektonAudit[enemyName].tier;
      if (champName === "エイトロックス") {
        if (["フィオラ","イレリア","アンベッサ"].includes(enemyName)) return 'extreme';
        if (["レネクトン","グウェン","ジャックス","リヴェン","ポッピー","ヴェイン","クイン"].includes(enemyName)) return 'disadvantage';
        if (["マルファイト","ナサス","ヨネ","ケイル","オーン"].includes(enemyName)) return 'advantage';
      }
      const override = currentWrRuneOverrides[champName];
      if (override?.advantage.has(enemyName)) return "advantage";
      if (override?.disadvantage.has(enemyName)) return "disadvantage";

      const explicitTip = champName === "モルデカイザー" ? mordekaiserTips[enemyName]
        : champName === "レネクトン" ? renektonTips[enemyName]
        : champName === "グウェン" ? gwenTips[enemyName]
        : champName === "ナー" ? gnarTips[enemyName]
        : champName === "オーン" ? ornnTips[enemyName]
        : null;
      if (explicitTip) {
        const firstLine = String(explicitTip).split(/<br>|\n/)[0];
        // 「微不利〜五分」「五分〜微有利」のような混在は互角扱い。
        if (/五分/.test(firstLine) && !/極めて不利|非常に不利|絶対天敵|ハードカウンター/.test(firstLine)) return "even";
        if (/序盤有利.*終盤不利|終盤注意/.test(firstLine)) return "even";
        if (/極めて不利|非常に不利|明確に不利|かなり不利|不利|ハードカウンター|絶対天敵/.test(firstLine)) return "disadvantage";
        if (/極めて有利|非常に有利|明確に有利|かなり有利|微有利|有利/.test(firstLine)) return "advantage";
      }
      return fallbackUnfavorable ? "disadvantage" : "even";
    }


    const rangedEnemies = new Set(["ヴァルス","ヴェイン","オーロラ","カシオペア","クイン","ケネン","ジェイス","トリスターナ","ツイステッド・フェイト","ナー","ハイマーディンガー","ティーモ","ライズ","ブラッドミア","ケイル"]);
    const burstEnemies = new Set(["アンベッサ","アカリ","リヴェン","ダリウス","パンテオン","ジャックス","セト","レンガー","ワーウィック","フィオラ","トリンダメア","イレリア","エイトロックス"]);
    const ccEnemies = new Set(["オーン","グラガス","カ・サンテ","シェン","マオカイ","サイオン","スカーナー","ノーチラス","ザック","ケネン","ライズ","レック＝サイ","リヴェン","ウディア"]);




    /*
     * エイトロックスのアイテム監査（再調査）
     *
     * 優先順位：
     * 1) MOBAFire：高レートTopの対面・ビルド理由
     * 2) Onetricks.gg：Masters+ OTPの実使用傾向
     * 3) WR資料：現行アイテムの存在・数値・仕様確認
     * 4) 最終判断：上記をWRへ翻訳した考察
     *
     * 結論：赤月の刃（Eclipse）はエイトロックスのQ/Eによる「短時間に2回別スキルを当てる」
     * 形と非常に噛み合い、現行の高レートMOBAFireでも主軸。サンダード スカイは2手目の有力候補。
     * ディヴァイン サンダラー（DS）はWRに現存し、HP・AD・スキルヘイスト＋Spellbladeで
     * 高HP/フロントライン戦に強いが、現行Aatroxの高レート実使用で標準コアとまでは確認できない。
     * したがって「万能な初手」にはせず、HPスタッカーが複数いる場合の対面/構成対応として採用する。
     */
    const aatroxFirstCore = {
      "フィオラ": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "エクスキューショナー系を優先候補", reason: "MOBAFireではフィオラに対して回復阻害の早期購入が強く推奨される。一方、完成コアは赤月の刃を主軸にしてQ/Eの短い接触で圧力を作り、次にサンダード スカイで1回目のAAと回復効率を補う。DSはフィオラ単体の対面では優先度を上げない。" },
      "イレリア": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "プレートスチールキャップ候補", reason: "イレリア側の連続Q接近とAA密度に対して、まず赤月の刃で短いQ交換の火力・シールドを確保。2手目はサンダード スカイで1回目のAAを強化し、長い追走を避けながら再交換を可能にする。" },
      "アンベッサ": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "プレートスチールキャップ候補", reason: "連続ダッシュへQを合わせる必要があるため、初手は赤月の刃の即応性を優先。サンダード スカイは2手目に回して、アンベッサの再接近を受けた後の反撃1発を強化する。" },
      "レネクトン": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "プレートスチールキャップ候補", reason: "レネクトンの強化W＋Eの短い物理バーストへ、赤月の刃のシールドとAD/ヘイストで交換窓を作る。高HP対策より短い接触の質が重要なのでDS初手にはしない。" },
      "リヴェン": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "プレートスチールキャップ候補", reason: "高機動ファイターには赤月の刃でQ/Eの接触を強化。リヴェンのコンボ後に1回だけ強いAAを差し込むサンダード スカイを2手目候補にする。" },
      "ダリウス": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "プレートスチールキャップ候補", reason: "Q外周とEを避ける技術が重要な対面。赤月の刃で短いQ交換の効率を上げ、サンダード スカイを2手目にして長期戦へ入る前の反撃火力を補強する。" },
      "セト": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "プレートスチールキャップ候補", reason: "セトWの中心を避けながら短い交換を重ねる。赤月の刃のシールドがWの返しを受ける余裕を作り、2手目サンダード スカイでAA込みの反撃を強化する。" },
      "ジャックス": { item: "赤月の刃 → ブラック クリーバー", firstPurchase: "プレートスチールキャップ候補", reason: "Jax E中にAAを無理に置かず、赤月の刃はQ/Eのスキル接触で起動する。2手目はブラック クリーバーでHP・ヘイスト・防具削りを確保し、E後の継続交換へ寄せる。" },
      "グウェン": { item: "赤月の刃 → デス ダンス", firstPurchase: "状況に応じてマーキュリートレッド候補", reason: "グウェンは長い接触で削り合うほど強くなるため、赤月の刃で最初の2スキル接触の火力とシールドを確保。2手目はデス ダンスでバースト耐性を足し、R中の継続戦闘時間を稼ぐ。" },
      "マルファイト": { item: "ブラック クリーバー → ディヴァイン サンダラー", firstPurchase: "ピッケル/AD素材を優先しつつ、防具圧が強ければブーツ素材", reason: "マルファイト本人の防具と、敵チームの前衛化が問題になる場合はブラック クリーバー初手が安定。DSは2手目から高HP相手へ追加し、Spellbladeの反復で長い接触を支える。" },
      "オーン": { item: "ブラック クリーバー → ディヴァイン サンダラー", firstPurchase: "ピッケル/AD素材を優先", reason: "高HP＋防具の単体対面ではブラック クリーバーの防具削りを先に作る価値が高い。さらに敵側に高HPの前衛が2体以上いるなら、2手目DSへ寄せてSpellbladeの最大HPダメージと回復で長期戦を補強する。" },
      "サイオン": { item: "ブラック クリーバー → ディヴァイン サンダラー", firstPurchase: "ピッケル/AD素材を優先", reason: "高HPタンク対面。まずブラック クリーバーでQ/Wの反復ダメージを通しやすくし、DSは2手目以降に回して最大HP依存のSpellbladeを長期交換へ活かす。" },
      "チョーガス": { item: "ブラック クリーバー → ディヴァイン サンダラー", firstPurchase: "ピッケル/AD素材を優先", reason: "最大HPが膨らむほどDSの価値が上がる。ただしAatroxは多段スキルでブラック クリーバーのスタックも作りやすいため、まずBCで継続火力を安定させ、DSを次に置くのが堅い。" },
      "ドクター・ムンド": { item: "ブラック クリーバー → ディヴァイン サンダラー", firstPurchase: "ピッケル/AD素材を優先", reason: "高HP＋回復量が問題になるため、BCの継続的な防具削りを起点にDSでHPバーへ直接圧力をかける。回復阻害が必要ならコア順を崩して先に確保する。" },
      "タム・ケンチ": { item: "赤月の刃 → ディヴァイン サンダラー", firstPurchase: "ピッケル/AD素材を優先", reason: "灰色体力による長い交換ではDSのHP・回復・Spellbladeが活きる。初手赤月の刃でQ/Eの短い接触を強化し、2手目DSで長期戦へ寄せる。" },
      "ナー": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "ブーツ＋AD素材を優先", reason: "ミニナーの射程管理とメガ化前後の接触窓を考え、初手は赤月の刃で短いQ/E接触を強化。DSは遠距離回避が多くSpellbladeの発動回数を稼ぎにくいため優先しない。" },
      "ヴェイン": { item: "赤月の刃 → スピア オブ ショージン", firstPurchase: "ブーツを早めに購入候補", reason: "射程差が大きく、まず接近回数を増やす必要がある。赤月の刃でQ/E接触時のシールドを確保し、2手目はスキル回転で追撃機会を増やす。DSは接近後のAA回数が安定しないため優先度が低い。" },
      "クイン": { item: "赤月の刃 → スピア オブ ショージン", firstPurchase: "ブーツを早めに購入候補", reason: "クインのEノックバックとQブラインドでSpellbladeのAA窓が崩れやすい。まず赤月の刃、次にスキル回転と追撃機会を増やす方向を優先し、DSは採用しない。" },
      "ティーモ": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "マーキュリートレッド素材候補", reason: "Qブラインド中でもQ/Eで赤月の刃を起動できるため、AA依存を避けられる。サンダード スカイは2手目に置き、近距離へ入れた後の一撃を強化する。" },
      "ケネン": { item: "赤月の刃 → デス ダンス", firstPurchase: "マーキュリートレッド素材候補", reason: "AP/CCバーストへ耐える必要があるため、赤月の刃で攻撃とシールドを両立し、2手目デス ダンスは物理面中心の防御だが、集団戦で突入後に生き残る時間を稼ぐ目的で採用。" },
      "アカリ": { item: "赤月の刃 → デス ダンス", firstPurchase: "マーキュリートレッド候補", reason: "煙幕内の視認性と接近を崩されやすいので、赤月の刃で接触時の瞬間火力とシールドを確保。DSはAA窓を作りにくいため採用優先度を下げる。" },
      "default": { item: "赤月の刃 → サンダード スカイ", firstPurchase: "AD素材を優先。対面がAA主体なら防具素材も検討", reason: "現行MOBAFireの高レートAatrox資料では赤月の刃が主軸で、サンダード スカイが有力な2手目。WR資料でも赤月の刃は高AD＋ヘイスト＋2回接触でシールド、サンダード スカイはAD＋HP＋ヘイストと初回AA強化を持つ。DSは現行WRに存在するが、Aatroxで標準コアとする高レート実使用根拠は弱いため、2体以上の高HP/前衛構成や長いサイド戦でのみ優先度を上げる。" }
    };
    // 重複キーを避けるため、上記の意図を維持して最終定義を上書き
    aatroxFirstCore["フィオラ"] = { item: "赤月の刃 → サンダード スカイ", firstPurchase: "エクスキューショナー系を優先候補", reason: "MOBAFireではフィオラに対して回復阻害の早期購入が強く推奨される。完成コアは赤月の刃を主軸にしてQ/Eの短い接触で圧力を作り、次にサンダード スカイで1回目のAAと回復効率を補う。DSはフィオラ単体の対面では優先度を上げない。" };
    function getAatroxFirstCore(enemyName) { return aatroxFirstCore[enemyName] || aatroxFirstCore.default; }

    function getChampionCoreText(champName, enemyName) {
      if (champName === 'エイトロックス') return getAatroxFirstCore(enemyName)?.item || '';
      if (champName === 'モルデカイザー') return getMordekaiserFirstCore(enemyName)?.item || '';
      if (champName === 'レネクトン') return getRenektonFirstCore(enemyName)?.item || '';
      if (champName === 'グウェン') return getGwenFirstCore(enemyName)?.item || '';
      if (champName === 'ナー') return getGnarFirstCore(enemyName)?.item || '';
      if (champName === 'オーン') return getOrnnFirstCore(enemyName)?.item || '';
      return '';
    }

    function getMatchupRuneSet(champName, enemyName, disposition) {
      /*
       * Wild Rift 7.2d: Keystone + メイン3枠 + サブ1枠。
       * 方針：有利/五分は栄華メイン、不利は不滅メイン。
       * ルーン名・効果はWR 7.2系を基準にし、MOBAFireの対面別運用を考察して決定。
       */
      const core = getChampionCoreText(champName, enemyName);
      const hasASCore = /黄昏と暁|実験的ヘクスプレート|ナッシャー/.test(core);
      const ranged = rangedEnemies.has(enemyName);
      const burst = burstEnemies.has(enemyName);
      const cc = ccEnemies.has(enemyName);

      // レネクトンは、遠距離対面や短い交換を繰り返したい一部対面で
      // MOBAFireの複数ガイドがPress the Attackを推奨。WRでは「エンパワーメント」。
      // 特にヴェインは複数ガイドで一致しており、ティーモ／ケネン／ナー／ジェイスも短時間
      // のE→AA→W→Q→E交換との噛み合わせが明確。GPとクインは現行ガイドで征服者推奨が
      // あるため、統計だけでエンパワーメントへ寄せず今回は征服者を維持する。
      const renektonEmpowermentMatchups = new Set([
        'ヴェイン','ティーモ','ケネン','ナー','ジェイス'
      ]);
      const gnarFleetMatchups = new Set([
        'イレリア','アカリ','ジャックス','クイン','ヴェイン','ケネン','ティーモ','リヴェン','トリンダメア','マルファイト','ジェイス','ヨネ','ヤスオ','セト'
      ]);
      const gnarConqMatchups = new Set(['ダリウス','イラオイ','オーン','チョーガス','サイオン','タム・ケンチ','モルデカイザー','ガレン','スカーナー']);

      // モルデカイザー：キーストーンは対面を問わず征服者で固定。
      // レンジ対面でもR（死の領域）で1vs1を強制できるため、序盤に殴れないことを理由に
      // フリートフットワークへ逃がさず、ファイターとしての継続戦闘性能を優先する。
      let keystone = (champName === 'モルデカイザー' || champName === 'エイトロックス')
        ? '征服者'
        : (champName === 'レネクトン' && renektonAudit[enemyName])
          ? renektonAudit[enemyName].keystone
          : (champName === 'レネクトン' && renektonEmpowermentMatchups.has(enemyName))
          ? 'エンパワーメント'
          : (champName === 'オーン')
            ? ([...rangedEnemies].includes(enemyName) ? 'エアリー召喚' : '不死者の握撃')
            : (champName === 'ナー' && gnarFleetMatchups.has(enemyName))
              ? 'フリートフットワーク'
              : (champName === 'ナー' && gnarConqMatchups.has(enemyName))
                ? '征服者'
                : 'フリートフットワーク';
      let mainTree;
      let main = [];
      let subTree;
      let sub;
      let reason = '';

      if (champName === 'エイトロックス') {
        if (disposition === 'disadvantage' || disposition === 'extreme') {
          mainTree = '不滅'; subTree = '栄華';
          main = ['堅忍不抜', ranged ? '息継ぎ' : 'ボーンアーマー', cc ? '忍耐' : '超成長'];
          sub = 'ブルータル';
          reason = '不利対面では不滅3枠でレーンを安定させ、サブ栄華で最低限の交換火力を確保する。征服者は固定。';
        } else {
          mainTree = '栄華'; subTree = '不滅';
          main = ['征服者','背水の陣', cc ? 'レジェンド：強靭' : 'レジェンド：迅速'];
          sub = burst ? 'ボーンアーマー' : (ranged ? '息継ぎ' : '超成長');
          reason = '有利・五分対面では征服者でQ連続ヒットから長期戦の火力を伸ばし、サブ不滅で対面別の耐久を確保する。';
        }
        return { runeText: `${keystone} / ${mainTree}: ${main.join(' / ')} / ${subTree}: ${sub}`, reason, structure: `メイン${mainTree}（3枠）＋サブ${subTree}（1枠）` };
      }

      if (champName === 'オーン') {
        if ([...rangedEnemies].includes(enemyName)) {
          mainTree = '魔道'; subTree = '不滅';
          main = ['エアリー召喚','マナフローバンド','至高'];
          sub = burst ? 'ボーンアーマー' : (cc ? '忍耐' : '息継ぎ');
          reason = `遠距離対面では不死者の握撃を安定して発動しにくいためエアリー召喚。メインはエアリー＋マナフローバンド＋至高でレーン維持とスキル回転を補い、サブ不滅は${sub}で対面の主な負荷に対応する。`;
        } else {
          mainTree = '不滅'; subTree = '魔道';
          main = ['不死者の握撃','打ちこわし', burst ? 'ボーンアーマー' : (cc ? '忍耐' : '超成長')];
          sub = 'マナフローバンド';
          reason = disposition === 'disadvantage'
            ? `不利対面なので不滅3枠でレーンを耐える。${main.slice(1).join('・')}で主な脅威を抑え、サブはマナフローバンド。Pの現地購入と合わせてQ・W・Eを回し、リコールを減らす。`
            : `通常近接対面は不滅3枠を基本にする。${main.slice(1).join('・')}でレーン耐久を確保し、サブはマナフローバンド。Pの現地購入と合わせてスキル使用回数を増やし、レーン維持を優先する。`;
        }
        return { runeText: `${keystone} / ${mainTree}: ${main.join(' / ')} / ${subTree}: ${sub}`, reason, structure: `メイン${mainTree}（3枠）＋サブ${subTree}（1枠）` };
      }

      // 栄華メイン：有利/五分では攻撃性能を優先。
      if (disposition !== 'disadvantage') {
        mainTree = '栄華';
        subTree = '不滅';

        // 栄華1：通常攻撃依存度と継続戦闘の長さを優先して決定。
        let p1;
        if (champName === 'レネクトン') {
          p1 = (renektonAudit[enemyName]?.keystone === 'フリートフットワーク')
            ? 'ブルータル'
            : (renektonAudit[enemyName]?.keystone === 'エンパワーメント' ? 'エンパワーメント' : 'ブルータル');
        } else if (champName === 'グウェン') {
          p1 = 'ブルータル';
        } else if (champName === 'ナー') {
          p1 = 'ブルータル';
        } else if (champName === 'モルデカイザー') {
          // モルデカイザーのキーストーンは征服者で固定。
          // ただし栄華1段目はアイテム構成で分岐する。
          // AS/通常攻撃・オンヒット寄りの構成ではブルータル、
          // AP/スキル持続火力寄りの構成ではバトルジールを優先。
          p1 = hasASCore ? 'ブルータル' : 'バトルジール';
        } else {
          p1 = 'ブルータル';
        }

        // 栄華2：ファイターは接近して殴り合う時間が長く、低体力まで戦う場面が多いので背水の陣を基本。
        // 栄華3：レジェンドは通常は迅速。CCが強い対面ではレジェンド：強靭を優先。
        const p2 = '背水の陣';
        const p3 = cc ? 'レジェンド：強靭' : 'レジェンド：迅速';
        main = [p1, p2, p3];

        // オーン：ベース外購入を活かしてリコール回数を減らし、マナを補ってレーン維持するためマナフローバンドを優先。
        if (champName === 'オーン') {
          subTree = '魔道';
          sub = 'マナフローバンド';
          reason = disposition === 'advantage'
            ? `有利対面なので不滅ではなく栄華をメインにする。${p1}・${p2}・${p3}で主導権を取り、サブのマナフローバンドでマナ持ちを補ってレーンを長く維持する。`
            : `五分対面なので栄華メインを基本にする。${p1}・${p2}・${p3}で勝ち筋を作り、サブのマナフローバンドでマナ持ちを補ってレーンを長く維持する。`;
        } else {
        // サブ不滅：有利対面で明確に欲しい対策がある場合はそれを優先。
        // モルデカイザー／レネクトンは自前の回復・シールドを持つため、生気付与を優先。
        // グウェンは特定の対策が必要ない有利対面では、超成長でレイトスケールを補強する。
        if (burst) sub = 'ボーンアーマー';
        else if (ranged) sub = '息継ぎ';
        else if (cc) sub = '忍耐';
        else if (/モルデカイザー|レネクトン/.test(champName)) sub = '生気付与';
        else if (champName === 'グウェン') sub = '超成長';
        else if (champName === 'ナー') sub = (ranged || burst) ? (burst ? 'ボーンアーマー' : '息継ぎ') : '超成長';
        else sub = '打ちこわし';

        if (champName === 'オーン') {
          // オーン以外の通常分岐では上記の不滅サブを使用。オーンはマナフローバンド固定。
        } else {
          reason = disposition === 'advantage'
            ? `有利対面なので栄華メインで攻める。${p1}・${p2}・${p3}で戦闘性能を伸ばし、サブ不滅は${sub}で有利を維持する。`
            : `五分対面なので栄華メインを基本形にする。${p1}・${p2}・${p3}で勝ち筋を作り、サブ不滅は対面のダメージ特性に合わせて${sub}。`;
        }

        if (champName === 'モルデカイザー') {
          reason = `モルデカイザーは征服者固定。序盤にレンジ相手へ通常攻撃を当て続けられなくても、Q・E・パッシブで接近機会を作り、Lv5以降はRで1vs1を強制して継続戦闘へ持ち込める。フリートフットワークで序盤の移動・回復を補うより、殴り合いの時間を作った際の征服者の火力・回復を優先する。`;
        }

        if (champName === 'レネクトン' && renektonAudit[enemyName]) {
          reason = `【レネクトン個別判定】${renektonAudit[enemyName].reason}`;
        } else if (champName === 'レネクトン' && renektonEmpowermentMatchups.has(enemyName)) {
          reason += ' エンパワーメントは短い交換で発動させやすく、特にWを絡めた交換の瞬間火力を補う。';
        }
        }
      } else {
        // 不利対面：不滅メインでレーンを耐え、栄華を1枠だけサブに回す。
        mainTree = '不滅';
        subTree = '栄華';

        // 不滅1：CCを持って自分から受け止める対面なら巨人の勇気、それ以外は防御効率を優先。
        let r1;
        if (cc && /モルデカイザー|レネクトン|グウェン/.test(champName)) r1 = '巨人の勇気';
        else r1 = '堅忍不抜';

        // 不滅2：遠距離ハラスは息継ぎ、瞬間火力はボーンアーマー。
        let r2 = ranged ? '息継ぎ' : (burst ? 'ボーンアーマー' : '息継ぎ');

        // 不滅3：CCなら忍耐、長期的なレーン耐久なら超成長。
        let r3 = cc ? '忍耐' : '超成長';
        main = [r1, r2, r3];

        // サブ栄華：チャンピオンごとの継続戦闘特性を残す。
        if (champName === 'レネクトン') sub = 'ブルータル';
        else if (champName === 'グウェン') sub = 'ブルータル';
        else if (champName === 'ナー') sub = 'ブルータル';
        else if (hasASCore) sub = 'ブルータル';
        else sub = 'バトルジール';

        if (champName === 'オーン') {
          subTree = '魔道';
          sub = 'マナフローバンド';
          reason = `不利対面なので不滅メインでレーンを耐える。${r1}・${r2}・${r3}で対面の圧を受け止め、サブはマナフローバンドでマナ持ちを補ってレーン維持を優先する。`;
        } else {
          reason = `不利対面なので不滅メインでレーンを耐える。${r1}・${r2}・${r3}で対面の圧を受け止め、サブ栄華は${sub}で最低限の戦闘力を残す。`;
        }

        if (champName === 'モルデカイザー') {
          reason += hasASCore
            ? ' モルデカイザーはAS/通常攻撃・オンヒット寄りのアイテム構成なので、通常攻撃から追加ダメージを出しやすいブルータルを優先。'
            : ' モルデカイザーはAP/スキル持続火力寄りのアイテム構成なので、戦闘継続中の基本スキル火力を伸ばせるバトルジールを優先。';
        }

        if (champName === 'レネクトン' && renektonEmpowermentMatchups.has(enemyName)) {
          reason += ' エンパワーメントはレーン中の短い交換でもWを起点に発動させやすく、捕まえられた一瞬の火力を補う目的で採用。';
        }
      }

      return {
        runeText: `${keystone} / ${mainTree}: ${main.join(' / ')} / ${subTree}: ${sub}`,
        reason,
        structure: `メイン${mainTree}（3枠）＋サブ${subTree}（1枠）`
      };
    }

    
function getChampionMetaTip(champName, enemyName, isUnfavorable) {
      if (champName === 'エイトロックス') {
        const d = getMatchupDisposition(champName, enemyName, isUnfavorable);
        const r = getMatchupRuneSet(champName, enemyName, d);
        return { rune: `【対面別確定ルーン】${r.runeText}<br>【構成】${r.structure}<br>【選択理由】${r.reason}`, timeline: 'Lv1〜2はQで安全にCS。Lv3〜4はQ・W・Eの位置調整で短い交換を作り、Lv5以降はRで回復・攻撃力を伸ばせる窓を作る。1コア後はサイド圧と集団戦の両方でQの射線を確保する。' };
      }
      const meta = championMetaTips[champName];
      if (!meta) return null;
      const disposition = getMatchupDisposition(champName, enemyName, isUnfavorable);
      const runeSet = getMatchupRuneSet(champName, enemyName, disposition);

      let note = '';
      if (disposition === 'advantage') {
        note = '【有利・攻め】栄華をメインにして主導権を取りに行く。';
      } else if (disposition === 'even') {
        note = '【五分・標準】栄華をメインにした標準構成を基本とする。';
      } else {
        note = '【不利・耐える】不滅をメインにしてレーンを安定させる。';
      }

      return {
        rune: `${note}<br>【対面別確定ルーン】${runeSet.runeText}<br>【構成】${runeSet.structure}<br>【選択理由】${runeSet.reason}`,
        timeline: meta.timeline
      };
    }


    // ===== 高レート資料の再監査ポリシー =====
    // MOBAFireを第一評価基準とし、Diamond / Master / Grandmaster / Challenger の標準Top運用を主資料とする。
    // 無評価・無ランク・明確なオフメタは原則除外。古い高レート記事は、現行WRにも残る
    // アイテム/戦術の歴史資料としてのみ補助的に参照する。WRサイトは仕様確認を主用途とする。
    const strictSourceProfiles = {
      "エイトロックス": "最優先資料：MOBAFire［26.10］BECOME THE WORLD ENDER | (GRAND)MASTERS AATROX GUIDE（評価10・1002票・62、In-depth、2026-05-13更新）。主軸ビルドはEclipse→Sundered Sky系。補助：MOBAFire［26.4］Fundamentals Of Aatrox（9.5・112票）とOnetricks.gg Masters+ Aatrox。WR資料で赤月の刃/サンダード スカイ/ディヴァイン サンダラーの現行仕様を確認。PC版ランクはWRランクへ読み替えず、DS採用はWR翻訳上の構成条件付き考察とする。",
      "モルデカイザー": "最優先資料：MOBAFire［26.17］Challenger Mordekaiser Top Guide（9.5・273票・15、2026-08-31更新）。標準Top運用として採用。補助：［26.13］同Challenger版。WR側はアイテム/ルーン/仕様確認に限定し、勝率や対面評価の主根拠にはしない。",
      "レネクトン": "最優先資料：MOBAFire［26.17/26.16系］The Ultimate Guide to Renekton by RandumPersin（評価9.5・130票前後、In-depth、2026-03-29更新）。補助：MOBAFire［15.9］Challenger Renekton Guide（評価8.5・246票・39）は現行WRにも通用する対面原理のみ歴史資料として使用。Onetricks.ggのMasters+ Renekton OTP対面別ビルド・ルーン・スペル・レーン統計を実使用傾向の確認に利用。WRサイトはアイテム/ルーン仕様確認に限定し、WR勝率/Tierは相性評価の主根拠にしない。",
      "グウェン": "主資料：MOBAFire［Master+ Gwen Guide \"Snip Snip!\"］（8.9・85票・9）、［PATCH 26.3］Challenger Gwen Guide（10・223票・21）。Jungle専用・無評価・オフメタは除外。",
      "ナー": "最優先資料：MOBAFire［26.16］Diamond Gnar Guide（10・1737票・85、2026-08-12更新）および現行Gnar Top統計。補助：Onetricks.gg Masters+ Gnar。WR資料は仕様確認に限定し、PC版の対面原理・スペル評価を主基準とする。",
      "オーン": "主資料：MOBAFire［26.17］Master OTP Ornn In-Depth Guide（10・78票）。補助：高レートChallenger系の過去資料。オフメタ・無評価は除外。WRではPの現地購入のみ採用し、SRのアイテム強化は除外。"
    };

    function stripTipForDetail(tip) {
      return String(tip || '').replace(/【[^】]+】\s*/g, '').replace(/\s+/g, ' ').trim();
    }

    function inferFirstPurchase(champName, enemyName, coreText, disposition) {
      const t = String(coreText || '');
      if (champName === 'オーン') {
        const d = getOrnnMatchupDetails(enemyName);
        return d?.first_component || '対面に必要な耐性素材を最優先';
      }
      if (/プレートスチールキャップ/.test(t)) return 'ブーツ＋クロースアーマー系を優先';
      if (/マーキュリートレッド/.test(t)) return 'ブーツ＋ヌルマジックマント系を優先';
      if (/ルインドキングブレード/.test(t)) return 'ロングソード系のAD素材を優先';
      if (/ナッシャー/.test(t)) return '増幅の書系のAP素材を優先';
      if (/黄昏と暁/.test(t)) return '攻撃速度＋AP素材を優先';
      if (/リーライ/.test(t)) return 'AP＋HP素材を優先';
      if (/ロケットベルト/.test(t)) return 'ブーツ＋AP素材を優先';
      if (/トリニティフォース/.test(t)) return 'AD素材を優先。対面がAA主体なら防具素材を先行';
      if (/ディヴァイン サンダラー/.test(t)) return 'AD素材を優先。高HP相手なら完成を急ぐ';
      if (/終わりなき絶望/.test(t)) return 'HP素材＋対面の主ダメージに対応する耐性素材';
      if (/ケイニック・ルーケイン/.test(t)) return 'ヌルマジックマント系のMR素材を優先';
      if (/フローズンハート/.test(t)) return 'ブーツ＋アーマー素材を優先';
      if (/ブラック クリーバー|ブラッククリーバー|ブラック・クリーバー/.test(t)) return 'ロングソード系のAD素材を優先';
      if (/ソーンメイル/.test(t)) return 'ブランブルベスト系を優先';
      return disposition === 'disadvantage' ? '防御系の安価な素材を優先' : 'ファーストコアの主要素材を優先';
    }

    function parseCoreStages(coreText, champName, enemyName) {
      if (champName === 'オーン') {
        const d = getOrnnMatchupDetails(enemyName);
        if (d) return { first: d.first_completed || '', second: d.second_core || '' };
      }
      const parts = String(coreText || '').split(/\s*→\s*/).map(x => x.trim()).filter(Boolean);
      if (parts.length >= 2) return { first: parts[0], second: parts.slice(1).join(' → ') };
      if (parts.length === 1) return { first: parts[0], second: '対面と試合展開に応じて防御/貫通/継続火力へ分岐' };
      return { first: '個別指定なし', second: '個別指定なし' };
    }

    function normalizeGwenItemLine(customTips, enemyName) {
      if (!customTips || !gwenFirstCore) return customTips;
      const meta = getGwenFirstCore(enemyName);
      if (!meta || !meta.item) return customTips;
      const text = String(customTips);
      if (!text.includes('【アイテム】')) return text;
      return text.replace(/【アイテム】[^\n<]*(?:<br>)?/, `【アイテム】${meta.item}<br>`);
    }

    function getStrictMatchupResearchDetail(champName, enemyName, disposition, customTips) {
      if (champName === 'エイトロックス') {
        const a = getAatroxFirstCore(enemyName);
        const runeSet = getMatchupRuneSet(champName, enemyName, disposition);
        const spell = getChampionSpellTip(champName, enemyName);
        const parts = a.item.split(' → ');
        return {
          recommendation: a.item, rune: runeSet.runeText, spell,
          difficulty: ['フィオラ','イレリア','アンベッサ'].includes(enemyName) ? 'Lv1〜4が最も危険。Qを外されると交換効率が急落するため、1コアまでCS・HP・Qサイクルを優先。' : 'Lv3〜4でQ・W・Eが揃ってから交換条件が安定。Lv5以降はRで勝てる窓を作り、1コア後にサイド圧を強める。',
          enemyWin: ['フィオラ','イレリア','アンベッサ'].includes(enemyName) ? 'Qをダッシュやパリィで外し、Qのない時間に長く追撃して反撃すること。' : 'Qのスイートスポットを避けながらこちらのEまで吐かせ、次のQサイクル前に長い交換を仕掛けること。',
          trade: 'Q1で距離を作り、相手の主要移動スキル後にQ2→W→Q3。Eは位置調整または離脱用に残し、全Qを同じ軌道で撃たない。',
          firstComponent: a.firstPurchase || inferFirstPurchase(champName, enemyName, a.item, disposition),
          firstCompleted: parts[0] || '赤月の刃', secondCore: parts.slice(1).join(' → ') || 'サンダード スカイ',
          reason: a.reason,
          itemAnalysis: '【赤月の刃】Q/Eで短時間に2回別スキルを当てやすく、シールド込みで短い接触を強化。現行MOBAFire高レート資料でも主軸。 【サンダード スカイ】AD＋HP＋ヘイストと初回AA強化で、2手目の継続交換に自然。 【ディヴァイン サンダラー】WRでは現行アイテムとして存在し、HP＋AD＋ヘイストとSpellbladeで高HP相手に価値があるが、現行AatroxのMasters+実使用で標準コアとまでは確認できないため、2体以上の高HP/前衛や長いサイド戦で優先する。',
          source: strictSourceProfiles[champName]
        };
      }
      if (champName === 'レネクトン' && renektonAudit[enemyName]) {
        const a = renektonAudit[enemyName];
        const runeSet = getMatchupRuneSet(champName, enemyName, disposition);
        return {
          recommendation: `${a.firstCore} → ${a.secondCore}`,
          rune: runeSet.runeText,
          spell: a.spell,
          difficulty: a.difficulty,
          enemyWin: a.enemyWin,
          trade: a.trade,
          firstComponent: a.firstComponent,
          firstCompleted: a.firstCore,
          secondCore: a.secondCore,
          reason: a.reason,
          neverDo: a.neverDo,
          source: a.source
        };
      }

      if (champName === 'オーン' && typeof getOrnnMatchupDetails === 'function') {
        const d = getOrnnMatchupDetails(enemyName);
        if (d) {
          const runeSet = getMatchupRuneSet(champName, enemyName, disposition);
          const spell = getChampionSpellTip(champName, enemyName) || 'フラッシュ＋テレポートを基本。';
          const stages = parseCoreStages(d.recommended || '', champName, enemyName);
          return {
            recommendation: d.recommended,
            rune: runeSet.runeText,
            spell,
            difficulty: d.difficulty_time,
            enemyWin: d.enemy_win,
            trade: d.trade,
            firstComponent: d.first_component,
            firstCompleted: stages.first,
            secondCore: stages.second,
            reason: d.reason,
            source: d.source_note || strictSourceProfiles[champName]
          };
        }
      }

      const core = getChampionCoreText(champName, enemyName);
      const runeSet = getMatchupRuneSet(champName, enemyName, disposition);
      const spell = getChampionSpellTip(champName, enemyName) || 'フラッシュ＋テレポートを基本。';
      const raw = stripTipForDetail(customTips);
      const stages = parseCoreStages(core, champName, enemyName);

      let difficulty = '';
      if (champName === 'ナー') {
        if (disposition === 'disadvantage') difficulty = '序盤は相手の主力接近/ハラスが完成するLv3〜4を最警戒。Lv5〜1コアはメガ化を受けに使える窓だけ戦い、1コア後に主導権を取り返す。';
        else if (disposition === 'advantage') difficulty = 'Lv1〜2で射程差を押し付け、相手の主要スキルが揃うLv3以降はEを温存して小さく交換。Lv5以降はメガ化の窓で一気に有利を現金化。';
        else difficulty = 'Lv1〜2は射程差、Lv3〜4は相手の接近手段、Lv5以降はメガ化の有無が勝敗を左右する。';
      } else if (disposition === 'disadvantage') {
        difficulty = 'Lv3〜4の主力スキル完成後が最も危険。Lv5〜1コアまでは無理なオールインを避け、最初の完成アイテムで弱点を埋めてから再度交換。';
      } else if (disposition === 'advantage') {
        difficulty = 'Lv1〜2から主導権を取り、Lv3〜4は相手の主要スキルのクールダウン後だけ交換。Lv5以降は自分のパワースパイクを使ってウェーブとキル圧を同時に取る。';
      } else {
        difficulty = 'Lv3〜4のスキルが揃ってから交換の成否が分かれる。Lv5〜1コアは相手のパワースパイクを尊重し、1コア以降に自分の継続火力/耐久の強みを使う。';
      }

      let enemyWin = raw || '相手の主力コンボ・射程・CCをこちらのスキルを使い切った状態で受け続けること。';
      let trade = raw || '相手の主要スキル後に短く交換し、こちらの離脱スキルを残す。長期戦は自分のパワースパイクと相手のリソースを確認してから。';
      let reason = `${stages.first}を先に完成させて、この対面で最も厄介なダメージ/接近手段への回答を作る。2コア目は相手の防御・継続戦闘性能がどこまで伸びたかで分岐。`;

      // 既存の対面Tipsに明示された時間・交換情報は「ダメージトレード」へ優先転用。
      if (raw.length > 0 && /Lv1|Lv3|Lv5|Lv6|1コア|序盤|終盤/.test(raw)) {
        difficulty = raw.split(/。/).filter(Boolean).slice(0, 2).join('。') + '。';
      }

      return {
        recommendation: core || '対面別の完成アイテム指定なし',
        rune: runeSet.runeText,
        spell,
        difficulty,
        enemyWin,
        trade,
        firstComponent: inferFirstPurchase(champName, enemyName, core, disposition),
        firstCompleted: stages.first,
        secondCore: stages.second,
        reason,
        source: strictSourceProfiles[champName] || '高レートMOBAFire資料を優先。具体的記述が不足する箇所は一般則からの考察。'
      };
    }

    let currentMode = 'A';

    function initSelects() {
      const mySelect = document.getElementById('myChampSelect');
      const enemySelect = document.getElementById('enemyChampSelect');
      const championList = document.getElementById('championList');
      
      // 入力候補をdatalistへ登録
      championList.innerHTML = matchups
        .map(c => `<option value="${c.name}">${c.kana}</option>`)
        .join('');

      // 初期値設定 (自分: モルデカイザー, 対面: アーゴット)
      if(matchups.length > 0) {
        mySelect.value = "モルデカイザー";
        enemySelect.value = "アーゴット";
      }
    }

    function switchMode(mode) {
      currentMode = mode;
      document.getElementById('tabModeA').classList.toggle('active', mode === 'A');
      document.getElementById('tabModeB').classList.toggle('active', mode === 'B');
      
      document.getElementById('panelModeA').style.display = mode === 'A' ? 'block' : 'none';
      document.getElementById('panelModeB').style.display = mode === 'B' ? 'block' : 'none';

      if (mode === 'A') {
        filterChampsA();
      } else {
        renderModeB();
      }
    }

    function handleImgError(img, name) {
      const parent = img.parentElement;
      const fallbackDiv = document.createElement('div');
      fallbackDiv.className = 'champ-icon-fallback';
      fallbackDiv.innerText = name.charAt(0);
      parent.replaceChild(fallbackDiv, img);
    }

    function buildIconHtml(champ) {
      if (champ.id === "Zaahen") {
        return `<div class="champ-icon-fallback">ザ</div>`;
      }
      const iconUrl = `https://ddragon.leagueoflegends.com/cdn/15.4.1/img/champion/${champ.id}.png`;
      return `<img src="${iconUrl}" alt="${champ.name}" class="champ-icon" loading="lazy" onerror="handleImgError(this, '${champ.name}')">`;
    }

    function getMobafireTransUrl(champId) {
      const rawUrl = `https://www.mobafire.com/league-of-legends/champion/${champId.toLowerCase()}`;
      return `https://translate.google.com/translate?sl=en&tl=ja&u=${encodeURIComponent(rawUrl)}`;
    }

    // --- モードA (BAN/PICK全体検索) の描画 ---
    function renderCardsA(data) {
      const container = document.getElementById('champContainer');
      container.innerHTML = '';

      if (data.length === 0) {
        container.innerHTML = '<div class="no-result">該当するチャンピオンが見つかりません</div>';
        return;
      }

      const fragment = document.createDocumentFragment();

      data.forEach(c => {
        const card = document.createElement('div');
        card.className = 'card';
        
        const tagsHtml = c.types.map(t => `<span class="tag">${t}</span>`).join('');
        const vsList = c.unfavorable.replace(/、/g, " / ");
        const transUrl = getMobafireTransUrl(c.id);

        card.innerHTML = `
          <div class="champ-header">
            <div class="champ-icon-wrapper">${buildIconHtml(c)}</div>
            <div class="header-text">
              <span class="champ-name">${c.name}</span>
              <span class="vs-header-text">${c.name} vs ${vsList}</span>
            </div>
            <a href="${transUrl}" target="_blank" rel="noopener noreferrer" class="mobafire-trans-btn">
              📖 MOBAFire(和訳)
            </a>
          </div>
          <div class="section-block">
            <div class="section-title feature">◆ ${c.name} の特徴</div>
            <div class="tags-container">${tagsHtml}</div>
          </div>
          <div class="section-block">
            <div class="section-title matchup">◆ ${c.name} vs 苦手対面の立ち回り</div>
            <div class="matchup-target">【苦手/カウンター】 ${c.unfavorable}</div>
            <div class="tips-content">${c.tips}</div>
          </div>
        `;
        fragment.appendChild(card);
      });

      container.appendChild(fragment);
    }

    let timer;
    function onSearchInput() {
      clearTimeout(timer);
      timer = setTimeout(filterChampsA, 150);
    }

    function clearSearchInput() {
      const input = document.getElementById('searchInput');
      input.value = '';
      filterChampsA();
      input.focus();
    }

    function filterChampsA() {
      const input = document.getElementById('searchInput').value.toLowerCase().trim();
      
      if (!input) {
        renderCardsA(matchups);
        return;
      }

      const filtered = matchups.filter(c => {
        const nameMatch = c.name.toLowerCase().startsWith(input);
        const kanaMatch = c.kana.startsWith(input);
        const typeMatch = c.types.some(t => t.toLowerCase().includes(input));
        return nameMatch || kanaMatch || typeMatch;
      });

      renderCardsA(filtered);
    }

    // --- モードB (1vs1指定) の描画 ---
    function renderModeB() {
      const myInput = document.getElementById('myChampSelect').value.trim();
      const enemyInput = document.getElementById('enemyChampSelect').value.trim();

      // 日本語名だけでなく、かな入力でも候補を選べるようにする
      const myChamp = findMyChampion(myInput);
      const enemyChamp = findChampion(enemyInput);
      const myName = myChamp ? myChamp.name : myInput;
      const enemyName = enemyChamp ? enemyChamp.name : enemyInput;
      
      const container = document.getElementById('champContainer');
      if (!myChamp || !enemyChamp) {
        container.innerHTML = '<div class="no-result">自分と対面のチャンピオン名を候補から選択してください</div>';
        return;
      }

      // 同一チャンピオン同士の対面は無効
      if (myChamp.name === enemyChamp.name) {
        container.innerHTML = '<div class="no-result">同じチャンピオン同士の1vs1指定はできません</div>';
        return;
      }

      container.innerHTML = '';

      const isUnfavorable = myChamp.unfavorable.includes(enemyName);
      const tagsHtml = myChamp.types.map(t => `<span class="tag">${t}</span>`).join('');
      const transUrl = getMobafireTransUrl(myChamp.id);

      // 対面に応じたTips判定
      // モルデカイザーとレネクトンは、対面別の専用Tipsを優先表示
      let customTips = myChamp.tips;
      if (myName === "モルデカイザー" && mordekaiserTips[enemyName]) {
        customTips = mordekaiserTips[enemyName];
      } else if (myName === "レネクトン" && renektonTips[enemyName]) {
        customTips = renektonTips[enemyName];
      } else if (myName === "グウェン" && gwenTips[enemyName]) {
        customTips = normalizeGwenItemLine(gwenTips[enemyName].replace(/\n/g, "<br>"), enemyName);
      } else if (myName === "ナー" && gnarTips[enemyName]) {
        customTips = gnarTips[enemyName].replace(/\n/g, "<br>");
      } else if (myName === "オーン" && ornnTips[enemyName]) {
        customTips = ornnTips[enemyName].replace(/\n/g, "<br>");
      }

      const mordekaiserCore = myName === "モルデカイザー" ? getMordekaiserFirstCore(enemyName) : null;
      const renektonCore = myName === "レネクトン" ? getRenektonFirstCore(enemyName) : null;
      const gwenCore = myName === "グウェン" ? getGwenFirstCore(enemyName) : null;
      const gnarCore = myName === "ナー" ? getGnarFirstCore(enemyName) : null;
      const ornnCore = myName === "オーン" ? getOrnnFirstCore(enemyName) : null;
      const metaTip = getChampionMetaTip(myName, enemyName, isUnfavorable);
      const skillTip = championSkillTips[myName] || null;
      const spellTip = getChampionSpellTip(myName, enemyName);

      const card = document.createElement('div');
      card.className = 'card';

      card.innerHTML = `
        <div class="champ-header">
          <div class="champ-icon-wrapper">${buildIconHtml(myChamp)}</div>
          <div class="header-text">
            <span class="champ-name">${myChamp.name}</span>
            <span class="vs-header-text">${myChamp.name} vs ${enemyName}</span>
          </div>
          <a href="${transUrl}" target="_blank" rel="noopener noreferrer" class="mobafire-trans-btn">
            📖 MOBAFire(和訳)
          </a>
        </div>

        <div class="section-block">
          <div class="section-title feature">◆ ${myChamp.name} の特徴</div>
          <div class="tags-container">${tagsHtml}</div>
        </div>

        <div class="section-block">
          <div class="section-title matchup">◆ ${myChamp.name} vs ${enemyName} の相性と立ち回り</div>
          <div class="matchup-target">
            【対面相性】 ${isUnfavorable ? `<span style="color:#f87171;">⚠️ ${enemyName} は苦手な対面です</span>` : `<span style="color:#86efac;">有利候補・通常対面。攻める余地あり</span>`}
          </div>
          <div class="tips-content" style="margin-top: 8px;">
            ${(() => {
              const cleanTips = String(customTips || '')
                .replace(/【ルーン】[^\n<]*(?:<br>)?/g, '')
                .replace(/【スペル】[^\n<]*(?:<br>)?/g, '')
                .replace(/\n{2,}/g, '\n')
                .replace(/<br>\s*<br>/g, '<br>');
              const md = getStrictMatchupResearchDetail(myName, enemyName, getMatchupDisposition(myName, enemyName, isUnfavorable), cleanTips);
              return `${cleanTips}<br><br><strong>【推奨ルーン】</strong><br>${md.rune}<br><br><strong>【推奨スペル】</strong><br>${md.spell}`;
            })()}
          </div>
        </div>

        ${(() => {
          const d = getStrictMatchupResearchDetail(myName, enemyName, getMatchupDisposition(myName, enemyName, isUnfavorable), customTips);
          return `
        <div class="section-block">
          <div class="section-title feature">◆ 対面別・実戦判断</div>
          <div class="tips-content" style="line-height:1.8;">
            <strong>【推奨アイテム】</strong><br>${d.recommendation}<br><br>
            <strong>【推奨ルーン】</strong><br>${d.rune}<br><br>
            <strong>【推奨スペル】</strong><br>${d.spell}<br><br>
            <strong>【対面で苦しい時間帯】</strong><br>${d.difficulty}<br><br>
            <strong>【相手の主な勝ち筋】</strong><br>${d.enemyWin}<br><br>
            <strong>【ダメージトレード】</strong><br>${d.trade}<br><br>
            ${d.neverDo ? `<strong>【この対面で絶対にやってはいけないこと】</strong><br><span style="color:#fca5a5;">${d.neverDo}</span><br><br>` : ''}
            <strong>【最初の素材購入】</strong><br>${d.firstComponent}<br><br>
            <strong>【最初の完成アイテム】</strong><br>${d.firstCompleted}<br><br>
            <strong>【2コア目】</strong><br>${d.secondCore}<br><br>
            <strong>【この対面での判断理由】</strong><br>${d.reason}<br><br>
            <strong>【資料監査】</strong><br>${d.source}
          </div>
        </div>`;
        })()}

        ${skillTip ? `
        <div class="section-block">
          <div class="section-title feature">◆ スキル取り・上げ</div>
          <div class="tips-content"><strong>基本順</strong><br>${skillTip.order}</div>
          <div class="tips-content" style="margin-top: 10px;">${skillTip.detail}</div>
          <div class="tips-content" style="margin-top: 10px;">${skillTip.matchup}</div>
        </div>` : ''}

        ${metaTip ? `
        <div class="section-block">
          <div class="section-title feature">◆ ルーン・時間帯別の行動</div>
          <div class="tips-content"><strong>ルーン</strong><br>${metaTip.rune}</div>
          <div class="tips-content" style="margin-top: 10px;"><strong>時間帯</strong><br>${metaTip.timeline}</div>
        </div>` : ''}

        ${spellTip ? `
        <div class="section-block">
          <div class="section-title matchup">◆ サモナースペル対策</div>
          <div class="tips-content">${spellTip}</div>
        </div>` : ''}
      `;

      container.appendChild(card);
    }


    // ===== 新しい対面データ層 =====
    // 既存の5チャンピオン分の個別Tipsを1つのデータ層へ統合。
    // 今後はここへ champion -> enemy のデータを追加するだけでUIが拡張される。
    const matchupResearch = {
      "エイトロックス": aatroxTips,
      "モルデカイザー": mordekaiserTips,
      "レネクトン": renektonTips,
      "グウェン": gwenTips,
      "ナー": gnarTips,
      "オーン": ornnTips
    };

    // 既存資料に未記載だった対面。断定せず「要追加検証」として表示する。
    if (!mordekaiserTips["ぼりべあ"]) mordekaiserTips["ぼりべあ"] = "【相性: 要追加検証】ボリベアのQ接近とW2回目の回復を警戒。Eで距離を作り、W2回目を許す長期戦を避ける。";
    if (!gwenTips["ぼりべあ"]) gwenTips["ぼりべあ"] = "【相性: 要追加検証】Qスタックを作ってからEで接近し、ボリベアQとW2回目を同時に受けない。長追いを避ける。";
    if (!gwenTips["レック＝サイ"]) gwenTips["レック＝サイ"] = "【相性: 要追加検証】潜伏Wからのノックアップを横移動で避け、Qの中心部を当てて短く交換する。地下を追い回さない。";

    const matchupSourceAudit = {
      "エイトロックス": "MOBAFire［26.10］Grandmasters Aatrox Guide（評価10・1002票・In-depth）を主資料。Onetricks.gg Masters+で実使用傾向を補助。WR側は赤月の刃・サンダード スカイ・ディヴァイン サンダラーの現行存在/数値/仕様確認に使用。DSは現行WRで存在するがAatrox標準コアとしての高レート実使用根拠が弱いため、構成条件付きの考察として表示。",
      "モルデカイザー": "WR現行ビルド資料＋既存の高レート対面考察。対面別ランクを個別に確認できないものは断定を避ける。",
      "レネクトン": "WR Master+公式統計を確認。個別対面は現行WR資料と既存考察を照合し、PC版高レート記事をWR勝率の根拠にはしない。",
      "グウェン": "WR Master+公式統計を確認。現行ビルドはWR資料を優先し、個別対面は既存考察を補助資料として扱う。",
      "ナー": "WR現行ビルド資料を優先。個別対面の高レート記事が確認できない場合は考察扱い。",
      "オーン": "WR Master+公式統計・現行WRビルド資料を優先。PC版MOBAFireのMaster表記はWR資料として採用しない。"
    };

    const currentWrGlobalStats = {
      "エイトロックス": { winrate: null, rank: null, asOf: null },
      "オーン": { winrate: "51.1%", rank: "Master+ / 中国公式統計", asOf: "2026-08-29" },
      "グウェン": { winrate: "52.7%", rank: "Master+ / 中国公式統計", asOf: "2026-08-25" },
      "レネクトン": { winrate: "48.8%", rank: "Master+ / 中国公式統計", asOf: "2026-09-02" },
      "ナー": { winrate: null, rank: null, asOf: null },
      "モルデカイザー": { winrate: null, rank: null, asOf: null }
    };

    function normalizeSearch(s) {
      return (s || '').toLowerCase().trim().replace(/[\s　]/g,'');
    }

    // MATCHUPモードで「自分」に選択できる、現時点で対面研究済みの6体。
    // 「対面」は従来どおり全チャンピオンを選択可能。
    const researchedMyChampions = new Set([
      "エイトロックス",
      "レネクトン",
      "グウェン",
      "オーン",
      "ナー",
      "モルデカイザー",
      "フィオラ"
    ]);

    function getMyChampionSuggestions(query) {
      const q = normalizeSearch(query);
      const pool = matchups.filter(c => researchedMyChampions.has(c.name));
      if (!q) return pool;
      return pool.filter(c =>
        normalizeSearch(c.name).includes(q) ||
        normalizeSearch(c.kana).includes(q)
      ).slice(0, 12);
    }

    function findMyChampion(query) {
      const q = normalizeSearch(query);
      if (!q) return null;
      const pool = matchups.filter(c => researchedMyChampions.has(c.name));
      return pool.find(c =>
        normalizeSearch(c.name) === q ||
        normalizeSearch(c.kana) === q
      ) || pool.find(c =>
        normalizeSearch(c.name).includes(q) ||
        normalizeSearch(c.kana).includes(q)
      );
    }

    function findChampion(query) {
      const q = normalizeSearch(query);
      if (!q) return null;
      return matchups.find(c => normalizeSearch(c.name) === q || normalizeSearch(c.kana) === q) ||
        matchups.find(c => normalizeSearch(c.name).includes(q) || normalizeSearch(c.kana).includes(q));
    }
    function getSuggestions(query) {
      const q = normalizeSearch(query);
      if (!q) return matchups.slice();
      return matchups.filter(c => normalizeSearch(c.name).includes(q) || normalizeSearch(c.kana).includes(q)).slice(0, 12);
    }
    function showSuggestions(inputId, boxId, items) {
      const box = document.getElementById(boxId);
      box.innerHTML = items.map(c => `<div class="combo-item" data-name="${c.name}"><span class="combo-name">${c.name}</span><span class="combo-kana">${c.kana}</span></div>`).join('');
      box.classList.toggle('open', items.length > 0);
      box.querySelectorAll('.combo-item').forEach(el => el.addEventListener('mousedown', e => {
        e.preventDefault();
        document.getElementById(inputId).value = el.dataset.name;
        box.classList.remove('open');
        renderModeB();
      }));
    }
    function clearComboInput(inputId, boxId) {
      const input = document.getElementById(inputId);
      const box = document.getElementById(boxId);
      input.value = '';
      box.innerHTML = '';
      box.classList.remove('open');
      input.focus();
      document.getElementById('champContainer').innerHTML = '<div class="no-result">自分と対面のチャンピオンを選択してください</div>';
    }

    function onComboInput(inputId, boxId) {
      const input = document.getElementById(inputId);
      const suggestions = inputId === 'myChampSelect'
        ? getMyChampionSuggestions(input.value)
        : getSuggestions(input.value);
      showSuggestions(inputId, boxId, suggestions);
      const other = inputId === 'myChampSelect' ? 'enemyChampSelect' : 'myChampSelect';
      const otherChamp = findChampion(document.getElementById(other).value);
      if (findChampion(input.value) && otherChamp) renderModeB();
    }
    document.addEventListener('click', e => {
      if (!e.target.closest('.combo-shell')) document.querySelectorAll('.combo-suggestions').forEach(x => x.classList.remove('open'));
    });

    function parseDisposition(text) {
      const t = (text || '').replace(/<br>/g,' ');
      if (/極めて不利|非常に不利|絶対天敵/.test(t)) return 'extreme';
      if (/不利/.test(t)) return 'disadvantage';
      if (/有利/.test(t)) return 'advantage';
      if (/五分|微不利|微有利|注意が必要|やや不利|やや有利/.test(t)) return 'even';
      return 'unknown';
    }
    function dispositionLabel(d) {
      return ({advantage:'有利',even:'五分',disadvantage:'不利',extreme:'極めて不利',unknown:'要追加検証'})[d] || '要追加検証';
    }
    function getSpecificResearch(champName, enemyName) {
      const map = matchupResearch[champName];
      if (map && map[enemyName]) return map[enemyName];
      return '';
    }
    function getStageData(champName, enemyName) {
      let detail = null;
      try { detail = getStrictMatchupResearchDetail(champName, enemyName, getMatchupDisposition(champName, enemyName, false), getSpecificResearch(champName, enemyName)); } catch(e) {}
      if (champName === 'オーン' && ornnMatchupDetails[enemyName]) {
        const d = ornnMatchupDetails[enemyName];
        return { firstPurchase:d.first_component || '対面に応じて素材分岐', firstCore:d.first_completed || d.recommended?.split(' → ')[0] || '個別指定なし', secondCore:d.second_core || d.recommended?.split(' → ').slice(1).join(' → ') || '状況分岐', reason:d.reason || '' };
      }
      if (champName === 'モルデカイザー' && mordekaiserFirstCore[enemyName]) {
        const arr = mordekaiserFirstCore[enemyName].item.split(' → ');
        return { firstPurchase:'対面指定あり', firstCore:arr[0], secondCore:arr.slice(1).join(' → ') || '状況分岐', reason:mordekaiserFirstCore[enemyName].reason };
      }
      if (champName === 'レネクトン' && renektonFirstCore[enemyName]) {
        const arr = renektonFirstCore[enemyName].item.split(' → ');
        return { firstPurchase:'対面指定あり', firstCore:arr[0], secondCore:arr.slice(1).join(' → ') || '状況分岐', reason:renektonFirstCore[enemyName].reason };
      }
      if (champName === 'グウェン' && gwenFirstCore[enemyName]) {
        const arr = gwenFirstCore[enemyName].item.split(' → ');
        return { firstPurchase:'対面指定あり', firstCore:arr[0], secondCore:arr.slice(1).join(' → ') || '状況分岐', reason:gwenFirstCore[enemyName].reason };
      }
      if (champName === 'エイトロックス') {
        const a = getAatroxFirstCore(enemyName);
        const arr = a.item.split(' → ');
        return { firstPurchase:a.firstPurchase || 'AD素材を優先。対面に応じてブーツ/防具/回復阻害へ分岐', firstCore:arr[0], secondCore:arr.slice(1).join(' → ') || '状況分岐', reason:a.reason };
      }
      if (champName === 'ナー' && gnarFirstCore[enemyName]) {
        const arr = gnarFirstCore[enemyName].item.split(' → ');
        return { firstPurchase:'対面指定あり', firstCore:arr[0], secondCore:arr.slice(1).join(' → ') || '状況分岐', reason:gnarFirstCore[enemyName].reason };
      }
      if (detail) return { firstPurchase:detail.firstComponent, firstCore:detail.firstCompleted, secondCore:detail.secondCore, reason:detail.reason };
      return { firstPurchase:'未指定', firstCore:'未指定', secondCore:'試合展開で分岐', reason:'個別の高レート資料で確認できるまで断定しない。' };
    }
    function getSourceTier(champName, enemyName, tip) {
      if (champName === 'モルデカイザー' && enemyName === 'オラフ') return 'B+H：現行WRで存在するステイシス運用＋高レート歴史資料の対面原理';
      if (champName === 'エイトロックス') return 'A/B/H/I：MOBAFire高レートTopを主資料、Onetricks.gg Masters+を実使用傾向、WR資料を現行アイテム仕様、最終判断はWR向け考察として分離';
      if (champName === 'オーン' || champName === 'レネクトン' || champName === 'グウェン') return 'B：WR Master+公式統計・現行ゲーム内ビルドを主資料。対面別の著者ランクを確認できない項目は断定しない';
      return 'B/H/I：現行WR資料・歴史資料・考察を分離して表示';
    }

    function neverDoText(champName, enemyName, disposition, tip) {
      const t = (tip || '').replace(/<br>/g,' ');
      if (champName === 'エイトロックス' && ['フィオラ','イレリア','アンベッサ'].includes(enemyName)) return 'Qを先置きして相手のダッシュやパリィに全部外される展開に入らない。Eを攻めに使い切らず次のQの位置調整へ残す。';
      if (champName === 'エイトロックス' && enemyName === 'レネクトン') return 'レネクトンの強化W＋Eを正面から受けて長期戦にしない。Qが外れた直後に追撃し続けない。';
      if (champName === 'モルデカイザー' && enemyName === 'オラフ') return 'オラフR中にR/Eで捕まえようとしない。1コアのステイシスを後回しにして正面オールインもしない。';
      if (champName === 'オーン' && enemyName === 'フィオラ') return 'W・RをフィオラWに雑に当てない。サイドで長時間の1vs1を主戦場にしない。';
      if (champName === 'オーン' && enemyName === 'グウェン') return 'グウェンのQ中心部を受けながら長期戦を続けない。AP耐久を作らずに正面から殴り合わない。';
      if (champName === 'レネクトン' && enemyName === 'オーン') return 'フューリー不足で無理にオールインしない。長期戦を放置して終盤までタンク性能と正面戦を許さない。';
      if (champName === 'グウェン' && enemyName === 'フィオラ') return 'フィオラWを確認せずにQ中心部やRの重要弾を先出ししない。';
      if (disposition === 'extreme') return '相手の勝ち筋が完成した状態で正面オールインしない。CS・経験値・ウェーブ状態を優先する。';
      if (disposition === 'disadvantage') return '相手の主要スキルが残っている状態で先に全リソースを吐かない。長追いしない。';
      if (disposition === 'advantage') return '有利だからといって相手タワー下まで深追いし、離脱手段を失わない。';
      return '主要スキルのクールダウンを確認せず、こちらの離脱手段まで使い切った長期戦に入らない。';
    }

    // 改訂版1vs1描画。データ層とUIを分離し、今後の追加は matchupResearch の拡張だけで済む構造。
    renderModeB = function() {
      const myChamp = findChampion(document.getElementById('myChampSelect').value);
      const enemyChamp = findChampion(document.getElementById('enemyChampSelect').value);
      const container = document.getElementById('champContainer');
      if (!myChamp || !enemyChamp) {
        container.innerHTML = '<div class="no-result">自分と対面を入力し、候補から選択してください。部分一致検索に対応しています。</div>';
        return;
      }
      if (myChamp.name === enemyChamp.name) {
        container.innerHTML = '<div class="no-result">同じチャンピオン同士の1vs1指定はできません</div>';
        return;
      }
      const myName=myChamp.name, enemyName=enemyChamp.name;
      const tip=getSpecificResearch(myName,enemyName) || myChamp.tips;
      const disposition=parseDisposition(tip);
      const stages=getStageData(myName,enemyName);
      const global=currentWrGlobalStats[myName];
      const detail=getStrictMatchupResearchDetail(myName,enemyName,disposition,tip);
      const source=matchupSourceAudit[myName] || '個別のWR高レート資料を追加検証中。';
      const badgeClass='status-'+disposition;
      const winText=global?.winrate ? `現行WR Master+全体勝率 ${global.winrate}（${global.asOf}）` : '対面別勝率は未取得';
      const card=document.createElement('div'); card.className='card';
      card.innerHTML=`
        <div class="champ-header"><div class="champ-icon-wrapper">${buildIconHtml(myChamp)}</div><div class="header-text"><span class="champ-name">${myName}</span><span class="vs-header-text">${myName} vs ${enemyName}</span></div><a href="${getMobafireTransUrl(myChamp.id)}" target="_blank" rel="noopener noreferrer" class="mobafire-trans-btn">📖 MOBAFire</a></div>
        <div class="section-block">
          <div class="section-title matchup">◆ 相性判定</div>
          <div class="matchup-status"><span class="status-badge ${badgeClass}">${dispositionLabel(disposition)}</span><span class="source-tier">${winText}</span></div>
          <div class="source-tier">※「有利/五分/不利/極めて不利」は対面別資料の記述を正規化した評価。対面勝率の数値が取得できない場合、勝率を推測しません。</div>
        </div>
        <div class="section-block"><div class="section-title feature">◆ 初手・1コア・2コア</div>
          <div class="item-grid"><div class="item-stage"><div class="item-stage-label">初手</div><div class="item-stage-value">${stages.firstPurchase}</div></div><div class="item-stage"><div class="item-stage-label">1コア</div><div class="item-stage-value">${stages.firstCore}</div></div><div class="item-stage"><div class="item-stage-label">2コア</div><div class="item-stage-value">${stages.secondCore}</div></div></div>
          <div class="tips-content" style="margin-top:10px;">${stages.reason || detail.reason}</div>
          ${myName === 'エイトロックス' && detail.itemAnalysis ? `<div class="tips-content" style="margin-top:12px; padding-top:10px; border-top:1px solid rgba(255,255,255,.06);">${detail.itemAnalysis}</div>` : ''}
        </div>
        <div class="section-block"><div class="section-title matchup">◆ ${myName} vs ${enemyName} の個別対策</div><div class="tips-content">${tip}</div></div>
        <div class="section-block"><div class="section-title matchup">◆ この対面で絶対にやってはいけないこと</div><div class="tips-content never-do">${neverDoText(myName,enemyName,disposition,tip)}</div></div>
        <div class="section-block"><div class="section-title feature">◆ 実戦判断</div><div class="tips-content"><strong>【苦しい時間帯】</strong><br>${detail.difficulty}<br><br><strong>【相手の勝ち筋】</strong><br>${detail.enemyWin}<br><br><strong>【ダメージトレード】</strong><br>${detail.trade}<br><br><strong>【ルーン】</strong><br>${detail.rune}<br><br><strong>【スペル】</strong><br>${detail.spell}</div></div>
        <div class="section-block"><div class="section-title feature">◆ 資料監査</div><div class="source-tier"><strong>資料ランク：</strong>${getSourceTier(myName,enemyName,tip)}<br>${source}</div></div>`;
      container.innerHTML=''; container.appendChild(card);
    };

    // 初期化
    initSelects();
    renderCardsA(matchups);
